package com.overhand.app.audio

/** 48 kHz mono PCM, generated by tools/earcons/generate.py. No ambient track. */
enum class Earcon(val file: String) {
  SELECT("select"), CONFIRM("confirm"), DEFER("defer"), NEEDS_YOU("needs_you"), DONE("done"),
  /** t1282: a grab or resize took hold. Never SELECT: SELECT means a control was chosen. */
  GRAB("grab");
  val path get()="audio/$file.wav"
}

/** Polling never repeats an unchanged notification; initial historical completions are silent. */
class AudioEvents {
  private val attention=mutableMapOf<String,Boolean>()
  private val tasks=mutableMapOf<String,String>()
  private var primed=false
  fun station(id: String,needs: Boolean): Earcon? {
    val previous=attention.put(id,needs)
    return if(needs && previous!=true) Earcon.NEEDS_YOU else null
  }
  fun task(id: String,status: String): Earcon? {
    val previous=tasks.put(id,status)
    return if(primed && previous!=null && previous!=status && status=="done") Earcon.DONE else null
  }
  fun finishSnapshot() { primed=true }
  companion object {
    fun replay(kind: String): Earcon?=when(kind) {
      "decision" -> Earcon.NEEDS_YOU
      "done" -> Earcon.DONE
      else -> null
    }
  }
}
